import {recipeIngredientMark} from './measuring-recipes-art.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Original inline illustrations. Every card retains its two guests and both portions.
export function batchCardArt(index=1,{example=false,hideAmounts=false}={}){return `<article class="wb-batch-card" aria-label="${example?'Supplied example: ':''}complete batch ${index}, two guests${hideAmounts?', find each ingredient amount':', 100 millilitres cloud-water and 150 millilitres star-water'}"><div class="wb-card-fold"><span>Complete batch ${index}</span><div class="wb-guests" aria-label="2 guests"><span aria-hidden="true">●<br>╰┴╯</span><span aria-hidden="true">●<br>╰┴╯</span><strong>2 guests</strong></div></div><div class="wb-card-portions"><div>${recipeIngredientMark('cloud-water')}<span>cloud-water</span><strong>${hideAmounts?'?':100} mL</strong><svg class="wb-mini-portion" viewBox="0 0 36 54" aria-hidden="true"><path d="M5 4h26v45H5Z" fill="#f2f7ef" stroke="#183f39" stroke-width="2"/><path d="M6 31h24v17H6Z" fill="#abc4da"/><path d="M7 39h22" stroke="#183f39" stroke-dasharray="2 4"/><circle cx="13" cy="34" r="1.5" fill="#183f39"/><circle cx="22" cy="44" r="1.5" fill="#183f39"/></svg></div><div>${recipeIngredientMark('star-water')}<span>star-water</span><strong>${hideAmounts?'?':150} mL</strong><svg class="wb-mini-portion" viewBox="0 0 36 54" aria-hidden="true"><path d="M5 4h26v45H5Z" fill="#f2f7ef" stroke="#183f39" stroke-width="2"/><path d="M6 23h24v25H6Z" fill="#e9b84a"/><path d="M7 31h22M7 39h22" stroke="#705a24" stroke-width="2"/></svg></div></div></article>`;}
export function batchLoafArt(){return `<svg viewBox="0 0 540 116" role="img" aria-label="The same whole loaf shown in two equal halves, then four equal quarters. Each quarter is one of four equal shares of the same whole." class="wb-loaf"><g fill="#e9b84a" stroke="#183f39" stroke-width="2"><rect x="12" y="12" width="220" height="65"/><path d="M122 12v65"/><rect x="305" y="12" width="220" height="65"/><path d="M360 12v65m55-65v65m55-65v65"/></g><g fill="#183f39" font-size="18" text-anchor="middle"><text x="122" y="104">same loaf · 2 equal halves</text><text x="415" y="104">same loaf · 4 equal quarters</text><text x="270" y="51">→</text></g></svg>`;}
export function batchGatheringArt(guests){return `<svg class="wb-gathering" viewBox="0 0 600 240" role="img" aria-label="An imagined gathering table with ${esc(guests)} places and two separate ingredient jars on an offered tray."><path d="M20 210Q160 170 300 205T590 190V240H20Z" fill="#eaf4ef"/><path d="M60 25q240 65 480 0" fill="none" stroke="#397958" stroke-width="3"/>${[90,195,300,405,510].map((x,i)=>`<path d="M${x} ${i%2?45:36}v27" stroke="#183f39"/><rect x="${x-10}" y="${i%2?67:58}" width="20" height="25" rx="7" fill="#e9b84a"/>`).join('')}<ellipse cx="300" cy="157" rx="235" ry="54" fill="#abc4da" stroke="#183f39" stroke-width="3"/>${Array.from({length:guests},(_,i)=>{const a=(i/guests)*Math.PI*2;return `<ellipse cx="${300+180*Math.cos(a)}" cy="${157+34*Math.sin(a)}" rx="21" ry="9" fill="#fffdf5" stroke="#397958" stroke-width="2"/>`;}).join('')}<rect x="237" y="133" width="126" height="46" rx="10" fill="#e9b84a" stroke="#183f39"/><rect x="256" y="112" width="32" height="53" rx="5" fill="#abc4da" stroke="#183f39"/><rect x="310" y="104" width="32" height="61" rx="5" fill="#e9b84a" stroke="#183f39"/><text x="272" y="146" text-anchor="middle" fill="#183f39">•••</text><text x="326" y="141" text-anchor="middle" fill="#183f39">///</text></svg>`;}
